// Extracts the SELF-INTERSECTING flag for the non-convex regular-faced shelf out of
// lib/render/nonconvexSolids.ts and writes it as data.
//
// WHY A SCRIPT AND NOT A FIELD. nonconvexSolids.ts is generated by tools/ctrnact-oracle/
// gen_nonconvex_shelf.py, which MEASURES this per solid ("some face edge passes through the interior of
// a face it shares no vertex with") and writes it into the comment above each entry — where no consumer
// can read it. Rather than re-deriving a delicate 3D predicate in TypeScript and hoping the two agree,
// this lifts the generator's own answer into a module the app can import.
//
// Re-run after any rebuild of that shelf: `node scripts/gen-ncx-crossing.mjs`. The test in
// tests/ncx-crossing.test.ts fails if the set and the shipped shelf disagree, so a stale run is loud.
import { readFileSync, writeFileSync } from "node:fs";

const src = readFileSync("lib/render/nonconvexSolids.ts", "utf8");
const crossing = [];
const embedded = [];
for (const line of src.split("\n")) {
	// ⚑ The flag is a comma-separated TOKEN, not the end of the line: ncx-7-15-10-a reads
	// "…, self-intersecting, inscribed" because it is the one solid on this shelf with a circumsphere.
	// Anchoring on the line end silently dropped it and the count came out 242 of 243.
	const m = /^\/\/ (ncx-[\w-]+)\s+—\s*(.*)$/.exec(line.trim());
	if (!m) continue;
	const tokens = m[2].split(",").map((t) => t.trim());
	const flag = tokens.find((t) => t === "self-intersecting" || t === "embedded");
	if (!flag) throw new Error(`no self-intersecting/embedded flag on: ${line.trim()}`);
	(flag === "self-intersecting" ? crossing : embedded).push(m[1]);
}
if (crossing.length + embedded.length === 0) throw new Error("no annotations found — did the comment format change?");
const dupes = crossing.filter((id) => embedded.includes(id));
if (dupes.length) throw new Error(`ids on both sides: ${dupes.join(", ")}`);

const out = `// GENERATED by scripts/gen-ncx-crossing.mjs from the comments in lib/render/nonconvexSolids.ts.
// Re-run it after rebuilding that shelf; tests/ncx-crossing.test.ts fails if this drifts from it.
//
// WHAT IT MEANS. A non-convex regular-faced solid is SELF-INTERSECTING when some face edge passes
// through the interior of a face it shares no vertex with, and EMBEDDED when none does — a polyhedron in
// the ordinary sense, non-convex but not passing through itself. The shelf holds both and they are
// different kinds of object, which is why the library lets you ask for one or the other.
//
// The measurement is the shelf generator's (tools/ctrnact-oracle/gen_nonconvex_shelf.py), not a second
// opinion computed here: it already does this while building the solids, and one delicate 3D predicate
// with one implementation is better than two that can disagree.

/** The ${crossing.length} solids whose faces pass through one another. */
export const NCX_SELF_INTERSECTING: ReadonlySet<string> = new Set([
${crossing.map((id) => `\t"${id}",`).join("\n")}
]);

/** The ${embedded.length} that do not: non-convex, but embedded. */
export const NCX_EMBEDDED: ReadonlySet<string> = new Set([
${embedded.map((id) => `\t"${id}",`).join("\n")}
]);

/** Whether this solid passes through itself. False for anything that is not on the "ncx-" shelf. */
export const ncxSelfIntersects = (solid: string | undefined): boolean =>
\tsolid != null && NCX_SELF_INTERSECTING.has(solid);
`;
writeFileSync("lib/tilings/ncx-crossing.ts", out);
console.log(`wrote lib/tilings/ncx-crossing.ts — ${crossing.length} self-intersecting, ${embedded.length} embedded`);
